import React from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import SignupForm from '../components/signup/SignupForm';
import { Link } from 'react-router-dom';
import SignupVisual from '../components/signup/SignupVisual';

const Signup = () => {
    return (
        <div className="bg-background text-on-background min-h-screen flex flex-col">
            <Header />

            {/* Main Content */}
            <main className="flex-grow flex items-center justify-center px-4 md:px-8 py-12 w-full animate-[fadeIn_0.5s_ease-out]">
                {/* Unified Card Container */}
                <div className="w-full max-w-[1000px] flex flex-col md:flex-row bg-surface-container-lowest rounded-[24px] shadow-2xl border border-outline-variant overflow-hidden mx-auto">

                    {/* Visual Section (Left Half) */}
                    <div className="w-full md:w-1/2 min-h-[300px] md:min-h-[600px] flex">
                        <SignupVisual />
                    </div>

                    {/* Form Section (Right Half) */}
                    <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col justify-center">
                        <SignupForm />
                    </div>

                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Signup;
